{
  "title": "The Bridge Out of Ashendral",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescue team studies a torn map of the ruined city.",
      "visual_description": "Three figures crouched at dusk on a hill overlooking a broken skyline of toppled spires and a long stone bridge, an unrolled map weighted with stones.",
      "characters": ["map_reader", "scout", "magic_helper"]
    },
    {
      "scene_number": 2,
      "caption": "They slip past the outer gate as a patrol marches by.",
      "visual_description": "Massive iron-banded gates hanging askew, armored guards with torches passing in formation while two figures press flat against a mossy wall.",
      "characters": ["scout", "map_reader", "armored_patrol"]
    },
    {
      "scene_number": 3,
      "caption": "On market street, frightened townspeople warn of dragons.",
      "visual_description": "A narrow lane of shuttered stalls and faded royal banners, a hunched old woman gesturing at scorch marks on the cobblestones.",
      "characters": ["map_reader", "scout", "frightened_townsperson"]
    },
    {
      "scene_number": 4,
      "caption": "The magic helper senses a curse on the eastern tower.",
      "visual_description": "A robed figure with glowing palms standing in a shaft of green light, the silhouette of a leaning black tower behind ragged clouds.",
      "characters": ["magic_helper", "map_reader"]
    },
    {
      "scene_number": 5,
      "caption": "A sleepy royal official is found dozing in a guard booth.",
      "visual_description": "A plump uniformed man slumped over a desk strewn with seals and half-eaten bread, a brass key ring dangling from his belt.",
      "characters": ["sleepy_official", "scout"]
    },
    {
      "scene_number": 6,
      "caption": "He grumbles, then agrees to guide them to the bridge controls.",
      "visual_description": "The official wagging a finger while the scout grins, lantern light catching the gold trim on his rumpled coat.",
      "characters": ["sleepy_official", "scout", "map_reader"]
    },
    {
      "scene_number": 7,
      "caption": "They cross the old plaza beneath tattered royal banners.",
      "visual_description": "A cracked fountain in a wide square, faded crimson banners snapping in a cold wind, four small figures crossing under a blood-orange sky.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official"]
    },
    {
      "scene_number": 8,
      "caption": "A patrol spots them; the scout creates a diversion.",
      "visual_description": "Armored soldiers pointing across the plaza as a cloaked figure hurls a clattering helmet down a side alley.",
      "characters": ["scout", "armored_patrol"]
    },
    {
      "scene_number": 9,
      "caption": "The team regroups inside a collapsed library.",
      "visual_description": "Toppled shelves, scattered illuminated pages, dust motes in slanted sunlight, the four companions catching their breath among broken statues.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official"]
    },
    {
      "scene_number": 10,
      "caption": "A rumor of a dragon proves to be a great painted banner.",
      "visual_description": "An enormous red dragon image flapping on canvas between two ruined towers, the scout laughing while pointing upward.",
      "characters": ["scout", "magic_helper"]
    },
    {
      "scene_number": 11,
      "caption": "The cursed tower bars their path with a sealed magic door.",
      "visual_description": "An obsidian arch carved with glowing runes, blue sparks crackling along iron rivets, the magic helper raising both hands.",
      "characters": ["magic_helper", "map_reader"]
    },
    {
      "scene_number": 12,
      "caption": "The magic helper unbinds the runes one by one.",
      "visual_description": "Concentric rings of light peeling away from the door as runes flicker out, the helper's hood pushed back by a rising wind.",
      "characters": ["magic_helper"]
    },
    {
      "scene_number": 13,
      "caption": "Inside the mirror hall they find the captive.",
      "visual_description": "A circular chamber walled with cracked mirrors reflecting a thin chained figure on a stone dais, multiple distorted reflections of the rescuers.",
      "characters": ["map_reader", "scout", "magic_helper", "captive"]
    },
    {
      "scene_number": 14,
      "caption": "The chains shatter at a whispered word.",
      "visual_description": "Iron links bursting into sparks of pale light, the captive sagging into the scout's arms, mirrors cracking outward in spider webs.",
      "characters": ["magic_helper", "scout", "captive"]
    },
    {
      "scene_number": 15,
      "caption": "A patrol thunders up the tower stairs behind them.",
      "visual_description": "Helmeted soldiers charging up a torchlit spiral, the rescuers fleeing upward through a broken window onto a roof.",
      "characters": ["armored_patrol", "scout", "captive", "map_reader"]
    },
    {
      "scene_number": 16,
      "caption": "At the bridge controls the official turns an enormous key.",
      "visual_description": "A vast brass mechanism of cogs and chains in a wind-blasted gatehouse, the sleepy official straining with both hands on a key the size of his arm.",
      "characters": ["sleepy_official", "map_reader", "captive"]
    },
    {
      "scene_number": 17,
      "caption": "They race across the rising stone bridge as it groans into place.",
      "visual_description": "A long arc of weathered stone spanning a chasm of mist, five figures sprinting silhouetted against a vast pale moon.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official", "captive"]
    },
    {
      "scene_number": 18,
      "caption": "On the far side, they look back at the ruined city one last time.",
      "visual_description": "Dawn breaking pink and gold over distant broken spires, the bridge collapsing slowly behind the silhouetted group on a grassy ridge.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official", "captive"]
    }
  ]
}

